interface BiomechanicFigureProps {
  defaultExercise?: 'pullup' | 'dips';
  className?: string;
}

export const BiomechanicFigure: React.FC<BiomechanicFigureProps> = ({
  defaultExercise = 'pullup',
  className = ''
}) => {
  const [selected, setSelected] = useState<'pullup' | 'dips'>(defaultExercise);

  return (
    <div className={`rounded-3xl bg-[#161b22] border border-[#30363d] p-6 space-y-4 shadow-xl ${className}`}>
      <div className="flex flex-col sm:flex-row justify-between sm:items-center gap-2 border-b border-[#30363d] pb-3">
        <div>
          <span className="text-[10px] font-mono font-bold text-[#58a6ff] uppercase tracking-wider block">
            Cinemática Biomecánica 2.5D
          </span>
          <h4 className="text-base font-bold text-white">
            {selected === 'pullup' ? 'Dominadas Estrictas (Pull-Ups)' : 'Fondos en Paralelas (Dips)'}
          </h4>
        </div>

        <div className="flex items-center gap-1.5 p-1 bg-[#0d1117] rounded-xl border border-[#30363d] self-start sm:self-auto">
          <button
            onClick={() => setSelected('pullup')}
            className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-colors ${
              selected === 'pullup'
                ? 'bg-[#1f6feb] text-white shadow-sm'
                : 'text-[#8b949e] hover:text-white'
            }`}
          >
            Dominadas
          </button>
          <button
            onClick={() => setSelected('dips')}
            className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-colors ${
              selected === 'dips'
                ? 'bg-[#1f6feb] text-white shadow-sm'
                : 'text-[#8b949e] hover:text-white'
            }`}
          >
            Fondos
          </button>
        </div>
      </div>

      <div className="w-full aspect-[4/3] max-h-[340px] flex items-center justify-center bg-[#0d1117] rounded-2xl overflow-hidden p-2 border border-[#30363d]/60">
        <div 
          className="w-full h-full flex items-center justify-center [&_svg]:max-h-full [&_svg]:w-auto [&_svg]:mx-auto [&_.toki-figure-stage]:w-full [&_.toki-figure-stage]:h-full [&_.toki-figure-stage]:flex [&_.toki-figure-stage]:items-center [&_.toki-figure-stage]:justify-center [&_.toki-figure-hud-tag]:hidden"
          dangerouslySetInnerHTML={{ __html: selected === 'pullup' ? PULLUP_SVG : DIPS_SVG }}
        />
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center text-[11px] font-mono text-[#8b949e] gap-1 px-1">
        <span className="flex items-center gap-1.5 text-[#3fb950]">
          <span className="w-2 h-2 rounded-full bg-[#3fb950] animate-pulse inline-block" />
          Activación Muscular Bioluminiscente
        </span>
        <span className="text-[#79c0ff]">
          {selected === 'pullup' ? 'Dorsal Ancho & Bíceps' : 'Pectoral & Tríceps'}
        </span>
      </div>
    </div>
  );
};

export default BiomechanicFigure;
